CREATE FUNCTION authz_int."membership__manage__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."membership__manage");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'membership.manage = group.manage';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."membership__group__manage");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'group.manage';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."group__manage" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."group_id" AS id FROM "fm"."group_members" r WHERE r."id" = p_id AND r."group_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'group', v_t.id, false) THEN
        RETURN NEXT pad || '       ' || 'group is a group you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'group is group '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has manage' ELSE ', without manage' END;
      IF NOT ('group:manage:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."group__manage__why"(v_t.id::uuid, p_depth + 1 + 1, p_seen || ('group:manage:' || v_t.id), p_asker);
      END IF;
    END LOOP;
  END;
END $f$;

