      IF p_asker IS NOT NULL AND NOT authz_int.asker_sees(p_asker, 'group', v_t.gid, false) THEN
        RETURN NEXT pad || 'yes  ' || 'editor: shared with' || ' a group you can''t see';
        RETURN;
      END IF;
      RETURN NEXT pad || 'yes  ' || 'editor: shared with' || ' group ' || v_t.gid || CASE WHEN p_asker IS NULL THEN ', and you are member there' ELSE ', and they are member there' END;
      RETURN QUERY SELECT * FROM authz_int."group__member__why"(v_t.gid::uuid, p_depth + 1, p_seen, p_asker);
